begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('private','event_cover_limits','configurable generation limits exist');
insert into auth.users(id,email) values('22260000-0000-4000-8000-000000000001','phase2@example.invalid'),('22260000-0000-4000-8000-000000000002','phase2other@example.invalid');
insert into public.organizers(id,display_name) values('22260000-0000-4000-8000-000000000001','Owner'),('22260000-0000-4000-8000-000000000002','Other');
insert into public.events(id,organizer_id,title,description,city) values('22260000-0000-4000-8000-000000000010','22260000-0000-4000-8000-000000000001','Saved jazz','Saved description','Oakland'),('22260000-0000-4000-8000-000000000011','22260000-0000-4000-8000-000000000001','Second','Other','Oakland');
insert into public.events(id,organizer_id) values('22260000-0000-4000-8000-000000000012','22260000-0000-4000-8000-000000000001');
select set_config('request.jwt.claim.sub','22260000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.create_event_cover_generation('22260000-0000-4000-8000-000000000012','22260000-0000-4000-8000-000000000023',0,'{}')$$,'P0001','COVER_SAVE_DETAILS','empty saved title cannot consume a generation set');
select public.create_event_cover_generation('22260000-0000-4000-8000-000000000010','22260000-0000-4000-8000-000000000020',0,'{"mood":"Editorial","direction":"blue"}');
select lives_ok($$select public.create_event_cover_generation('22260000-0000-4000-8000-000000000010','22260000-0000-4000-8000-000000000020',0,'{"mood":"Editorial","direction":"blue"}')$$,'duplicate creation is safe');
select throws_ok($$select public.create_event_cover_generation('22260000-0000-4000-8000-000000000011','22260000-0000-4000-8000-000000000021',0,'{}')$$,'P0001','COVER_ACTIVE','one active generation per organizer across events');
reset role;
select is((select context->>'title' from private.event_cover_generations where id='22260000-0000-4000-8000-000000000020'),'Saved jazz','saved context frozen server-side');
select is((select count(*) from private.event_cover_candidates where generation_id='22260000-0000-4000-8000-000000000020'),3::bigint,'exactly three slots');
select throws_ok($$select public.server_claim_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000002',0)$$,'P0001','COVER_NOT_OWNED','foreign execution denied');
select is(public.server_claim_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000001',0)->>'claimed','true','first attempt claimed');
select is(public.server_claim_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000001',0)->>'claimed','false','duplicate cannot execute provider again');
select throws_ok($$select public.server_finish_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000099',null,'PROVIDER_FAILED')$$,'P0001','COVER_CLAIM_LOST','wrong claim completion fenced');
update private.event_cover_candidates set lease_until=now()-interval '1 second',updated_at=now()-interval '5 minutes' where generation_id='22260000-0000-4000-8000-000000000020' and slot=1;
select public.server_recover_cover_generation('22260000-0000-4000-8000-000000000020','22260000-0000-4000-8000-000000000001');
select is((select status from private.event_cover_candidates where generation_id='22260000-0000-4000-8000-000000000020' and slot=1),'failed','interrupted claim becomes visible failure');
update private.event_cover_candidates set updated_at=now()-interval '1 minute' where generation_id='22260000-0000-4000-8000-000000000020' and slot=1;
select is(public.server_claim_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000001',1)->>'claimed','true','one explicit retry');
update private.event_cover_candidates set status='failed',failure_code='PROVIDER_FAILED',lease_until=null,claim_token=null,updated_at=now()-interval '1 minute' where generation_id='22260000-0000-4000-8000-000000000020';
select throws_ok($$select public.server_claim_cover_candidate('22260000-0000-4000-8000-000000000020',1::smallint,'22260000-0000-4000-8000-000000000001',2)$$,'P0001','COVER_RETRY_LIMIT','third attempt denied');
update private.event_cover_limits set event_daily=1;
set local role authenticated;
select throws_ok($$select public.create_event_cover_generation('22260000-0000-4000-8000-000000000010','22260000-0000-4000-8000-000000000022',0,'{}')$$,'P0001','COVER_EVENT_LIMIT','event daily limit enforced');
reset role;
update private.event_cover_limits set organizer_daily=1;
set local role authenticated;
select throws_ok($$select public.create_event_cover_generation('22260000-0000-4000-8000-000000000011','22260000-0000-4000-8000-000000000022',0,'{}')$$,'P0001','COVER_ORGANIZER_LIMIT','organizer daily limit enforced');
reset role;
select ok(not has_function_privilege('authenticated','public.server_claim_cover_candidate(uuid,smallint,uuid,integer)','execute'),'browser cannot claim directly');
select ok(not has_function_privilege('anon','public.create_event_cover_generation(uuid,uuid,bigint,jsonb)','execute'),'anonymous creation denied');
select * from finish();
rollback;
